// GPL compliance kit builders (spec: "Packaging & release" — libsidplayfp
// pattern). Called by tools/package/build-package.mjs.

import { spawnSync } from "node:child_process";
import { cpSync, existsSync, mkdirSync, mkdtempSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const PRUNE = new Set([
  ".git",
  ".github",
  ".vs",
  "bin",
  "obj",
  "node_modules",
  "artifacts",
  "_docs",
  "test-results",
  "playwright-report",
  "TestResults",
  // Build outputs / local-only trees that are gitignored upstream. Listed
  // explicitly because the source snapshot is taken from the working tree
  // rather than from `git archive` (see collectSourceTree).
  "dist",
  ".local-fixtures",
]);

/**
 * Builds the GPLv3 §3a Corresponding Source tarball:
 * this repo's tracked tree at HEAD plus the full vendored upstream subtree.
 */
export function buildCompleteSource(root, outFile) {
  // Staged in the OS temp dir, not under root/artifacts: an editor's .NET
  // language server watching the workspace design-time-builds every copied
  // .csproj, recreating obj/ dirs mid-cleanup (ENOTEMPTY). Outside the
  // workspace nothing watches it.
  const staging = mkdtempSync(join(tmpdir(), "pkhex-wasm-src-"));

  collectSourceTree(root, staging);

  const everywhereSrc = join(root, "external", "PKHeX.Everywhere");
  if (!existsSync(everywhereSrc)) {
    throw new Error("vendored submodule external/PKHeX.Everywhere is not checked out");
  }
  cpSync(everywhereSrc, join(staging, "external", "PKHeX.Everywhere"), {
    recursive: true,
    filter: (src) => !PRUNE.has(partAt(src, root)),
  });

  prune(staging);
  mkdirSync(join(staging, "artifacts"), { recursive: true });
  mkdirSync(root, { recursive: true });
  run("tar", ["-czf", outFile, "-C", staging, "."], root);
  rmSync(staging, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 });
}

/**
 * Snapshots this repo's own sources into `dest`.
 *
 * Upstream used `git archive HEAD`, which requires the tree to be a git
 * repository. A vendored copy (checked into a consuming repo, no nested .git)
 * has none, so the snapshot is taken from the working tree with the same
 * `PRUNE` exclusions applied. `external/` is skipped here because
 * buildCompleteSource copies the vendored upstream subtree separately.
 */
function collectSourceTree(root, dest) {
  // Walked by hand rather than via cpSync(root, ...) so PRUNE applies at every
  // depth and nothing under the workspace's own build outputs is traversed.
  mkdirSync(dest, { recursive: true });
  const walk = (relDir) => {
    const absDir = relDir ? join(root, relDir) : root;
    for (const entry of readdirSync(absDir, { withFileTypes: true })) {
      if (PRUNE.has(entry.name)) continue;
      const rel = relDir ? `${relDir}/${entry.name}` : entry.name;
      // Copied explicitly by buildCompleteSource with its own filtering.
      if (!relDir && entry.name === "external") continue;
      const from = join(root, rel);
      const to = join(dest, rel);
      if (entry.isDirectory()) {
        mkdirSync(to, { recursive: true });
        walk(rel);
      } else if (entry.isFile()) {
        cpSync(from, to);
      }
    }
  };
  walk("");
}

export function run(cmd, args, cwd) {
  // npm is npm.cmd on Windows; Node refuses to spawn .cmd without a shell.
  const res = spawnSync(cmd, args, { cwd, stdio: "inherit", shell: cmd === "npm" });
  if (res.status !== 0) throw new Error(`${cmd} ${args.join(" ")} exited ${res.status}`);
}

/** Path segment directly under `root` for `path`, or null when outside. */
function partAt(path, root) {
  const rel = path.slice(root.length).replace(/\\/g, "/").replace(/^\//, "");
  return rel.includes("/") ? null : rel;
}

function prune(dir) {
  for (const name of readdirSync(dir)) {
    const child = join(dir, name);
    if (!PRUNE.has(name)) {
      try {
        if (readdirSync(child)) prune(child);
      } catch {
        /* file */
      }
      continue;
    }
    rmSync(child, { recursive: true, force: true });
  }
}

export function writeUpstreamJson(stage, pins) {
  const upstream = {
    $comment: "Vendored upstream pins for pkhex-wasm. Regenerated by tools/package/build-package.mjs.",
    pkhexEverywhere: {
      url: "https://github.com/arleypadua/PKHeX.Everywhere.git",
      commit: pins.everywhere,
      license: "MIT",
      role: "vendored upstream monorepo hosting the PKHeX fork as a nested submodule",
    },
    pkhexCoreFork: {
      url: "https://github.com/arleypadua/PKHeX",
      commit: pins.fork,
      license: "GPL-3.0-or-later",
      role: "PKHeX.Core sources compiled into the shipped wasm bundle",
      vendoredCrypto: {
        source: "https://github.com/bcgit/bc-csharp",
        commit: "214b5f881be55d708e528ae43693a70211557075",
        license: "MIT",
        provenanceDoc: "src/PKHexWasm/Crypto/Vendored/PROVENANCE.md (in complete-source.tar.gz)",
      },
    },
    generatedAt: new Date().toISOString(),
  };
  writeFileSync(join(stage, "upstream.json"), `${JSON.stringify(upstream, null, 2)}\n`);
}
